from __future__ import annotations


GROUP_PAGE = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Joker 用户中心</title>
<style>
:root{font-family:"Microsoft YaHei",system-ui,sans-serif;--bg:#0b1220;--side:#101a2d;--panel:#142238;--panel2:#192b45;--line:#294666;--text:#eef5ff;--muted:#91a7c2;--accent:#22b7a5;--accent2:#ff7846;--danger:#df6171;--good:#79d9b1}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 78% -18%,#1b4262 0,transparent 37%),var(--bg);color:var(--text);min-height:100vh}.shell{display:grid;grid-template-columns:245px minmax(0,1fr);min-height:100vh}.side{background:#0d1728ed;border-right:1px solid var(--line);padding:23px 14px;display:flex;flex-direction:column;gap:17px}.brand{padding:0 11px}.brand strong{font-size:19px;letter-spacing:.2px}.brand span,.muted{display:block;color:var(--muted);font-size:12px;line-height:1.65;margin-top:5px}.nav-group{border-top:1px solid #213c5b;padding-top:12px}.nav-label{font-size:11px;color:#a9bbd1;padding:0 11px 6px;letter-spacing:.08em}.nav button{display:block;width:100%;border:0;background:transparent;color:#c7d3e4;text-align:left;padding:9px 11px;border-radius:8px;margin:1px 0;font:inherit;font-size:13px;cursor:pointer}.nav button:hover,.nav button.active{background:#193653;color:#fff;box-shadow:inset 2px 0 var(--accent)}.side-foot{margin-top:auto;padding:0 11px}.side-foot button,.button{border:1px solid #35587a;background:#1a3451;color:#eef6ff;padding:9px 12px;border-radius:7px;font:inherit;cursor:pointer}.button.primary{background:var(--accent);color:#062522;border-color:var(--accent);font-weight:700}.button.danger{background:#4a2934;border-color:#7b4352;color:#ffd1d8}.button.subtle{background:#13253b}.button:disabled{opacity:.5;cursor:not-allowed}.button:hover{filter:brightness(1.1)}.main{min-width:0}.top{padding:20px 31px;border-bottom:1px solid var(--line);background:#101d31d9;display:flex;align-items:center;justify-content:space-between;gap:18px}.top h1{margin:0;font-size:22px}.top p{margin:6px 0 0;color:var(--muted);font-size:13px}.scope{min-width:250px}.scope select,input,textarea{width:100%;background:#0c192b;border:1px solid #385a7a;color:var(--text);border-radius:7px;padding:10px;font:inherit}.content{max-width:1360px;margin:auto;padding:27px 31px 52px}.view{display:none}.view.active{display:block}.panel,.card{background:linear-gradient(145deg,#162841e8,#112039e8);border:1px solid var(--line);border-radius:11px;box-shadow:0 14px 32px #02091433}.panel{padding:20px;margin-bottom:17px}.card{padding:17px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.split{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);gap:17px}.panel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:15px}.panel h2,.panel h3{margin:0;font-size:16px}.panel p{margin:6px 0 0}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;align-items:end}.form.two{grid-template-columns:repeat(2,minmax(0,1fr))}.form label{display:grid;gap:6px;color:#b4c4d8;font-size:12px}.form label.full{grid-column:1/-1}.form textarea{min-height:90px;resize:vertical}.checks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.check{display:flex;gap:9px;align-items:flex-start;background:#102137;border:1px solid #284a68;padding:11px;border-radius:8px;color:#dbe8f7;font-size:13px}.check input{width:auto;margin:2px 0 0}.check small{display:block;color:var(--muted);margin-top:4px;line-height:1.5}.empty,.note{padding:18px;color:var(--muted);text-align:center;border:1px dashed #375775;border-radius:8px}.note{text-align:left;background:#102a3a;border-left:3px solid var(--accent);color:#cfe7eb;font-size:13px;line-height:1.65}.result{color:var(--good);font-size:13px;min-height:18px;margin-top:11px}.error{color:#ff9ca9}.tag{display:inline-block;border-radius:99px;padding:3px 8px;background:#143f3e;color:#94e7d1;font-size:11px}.tag.warn{background:#4b3424;color:#ffd49f}.tag.off{background:#3b2e39;color:#ffb2be}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid #284864;padding:10px 8px;text-align:left;vertical-align:top;line-height:1.5}th{color:#9cb3cf;font-weight:500}td button{margin-right:6px;margin-bottom:4px}.row-actions{display:flex;gap:8px;flex-wrap:wrap}.group-card{cursor:pointer;transition:.16s ease}.group-card:hover{border-color:var(--accent);transform:translateY(-2px)}.group-id{font-family:ui-monospace,Consolas,monospace;color:#9fc6ed;font-size:12px;margin-top:8px}.feature-meta{display:flex;justify-content:space-between;gap:8px;margin-bottom:5px}.feature-meta b{font-size:13px}.feature-meta span{font-size:11px;color:#8fd6c8}.mobile-only{display:none}@media(max-width:960px){.shell{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line);padding-bottom:14px}.nav{display:flex;gap:4px;overflow:auto}.nav button{white-space:nowrap;width:auto}.nav-group{padding-top:9px}.side-foot{display:none}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.split{grid-template-columns:1fr}.top{padding:17px 20px}.content{padding:21px 18px}.mobile-only{display:block}}@media(max-width:620px){.grid,.form,.form.two,.checks{grid-template-columns:1fr}.top{display:block}.scope{margin-top:13px;min-width:0}table{display:block;overflow:auto;white-space:nowrap}.content{padding:17px 13px}.panel{padding:15px}}
 </style></head><body><div class="shell"><aside class="side"><div class="brand"><strong>Joker 用户中心</strong><span>每个官方群独立保存配置</span></div><div class="nav-group"><div class="nav-label">群组</div><nav class="nav"><button class="active" data-view="groups">我的群</button><button data-view="bind">绑定官方群</button></nav></div><div class="nav-group"><div class="nav-label">基础设置</div><nav class="nav"><button data-view="switches">功能设置</button><button data-view="server">SCUM 服务器</button><button data-view="replies">自动回复</button><button data-view="user-replies">用户专属回复</button><button data-view="schedules">定时消息</button></nav></div><div class="nav-group"><div class="nav-label">审核与群管</div><nav class="nav"><button data-view="group-admins">分管管理员</button><button data-view="approval">入群审核</button><button data-view="moderation">手动群管</button><button data-view="blacklist">黑名单</button><button data-view="keyword-mute">关键词禁言</button><button data-view="keyword-kick">关键词踢出</button><button data-view="keyword-blacklist">关键词拉黑</button></nav></div><div class="nav-group"><div class="nav-label">记录与账号</div><nav class="nav"><button data-view="messages">群消息记录</button><button data-view="profile">账号资料</button></nav></div><div class="side-foot"><span class="muted" id="user-label">登录中</span><button id="logout">退出登录</button></div></aside><main class="main"><header class="top"><div><h1 id="title">我的群</h1><p id="subtitle">使用机器人授权卡注册账号后，在这里绑定并配置官方群。</p></div><label class="scope">当前群<select id="scope-switch"><option value="">暂未选择群</option></select></label></header><div class="content">
<section class="view active" id="groups"><div class="panel"><div class="panel-head"><div><h2>已绑定官方群</h2><p class="muted">点击群卡即可切换当前群。所有配置均只作用于当前群。</p></div><button class="button primary" data-view="bind">绑定官方群</button></div><div id="groups-list" class="grid"></div></div></section>
<section class="view" id="bind"><div class="split"><div class="panel"><div class="panel-head"><div><h2>绑定官方群</h2><p class="muted">当前账号已由机器人授权卡授权。填写官方群 OpenID 即可绑定，不需要第二张卡密。</p></div></div><div class="form two"><label>官方群 OpenID<input id="bind-scope" placeholder="官方群 group_openid"></label><div><button id="bind-group" class="button primary">绑定当前群</button></div></div><div class="result" id="bind-result"></div></div><div class="panel"><h3>如何获取官方群 OpenID</h3><p class="muted">在目标官方群内发送 <code>/获取OpenID</code>。机器人回复的第一行“群 OpenID”就是这里需要填写的值；它是 QQ 官方群标识，不是分群账号，也不是传统数字 QQ 群号。</p></div></div></section>
<section class="view" id="switches"><div class="panel"><div class="panel-head"><div><h2>功能设置</h2><p class="muted">每个功能独立启停；需要规则、内容或成员参数的功能可直接进入设置页。</p></div></div><div id="switch-list" class="grid"></div><div id="switch-result" class="result"></div></div></section>
<section class="view" id="server"><div class="panel"><div class="panel-head"><div><h2>SCUM 服务器</h2><p class="muted">为当前群绑定服务器后，成员可使用在线查询。</p></div></div><div class="form two"><label>SCUM 服务器 ID<input id="server-id" inputmode="numeric" placeholder="例如 41726514"></label><div><button id="save-server" class="button primary">保存服务器</button></div></div><div id="server-result" class="result"></div></div></section>
<section class="view" id="replies"><div class="split"><div class="panel"><div class="panel-head"><div><h2>自动回复</h2><p class="muted">收到完全匹配的关键词时自动回复。</p></div></div><div class="form two"><label>关键词<input id="reply-trigger" maxlength="128"></label><label>回复内容<input id="reply-response" maxlength="2000"></label></div><button id="add-reply" class="button primary" style="margin-top:12px">添加自动回复</button><div id="reply-result" class="result"></div></div><div class="panel"><h3>已配置回复</h3><div id="reply-list"></div></div></div></section>
<section class="view" id="user-replies"><div class="split"><div class="panel"><div class="panel-head"><div><h2>用户专属回复</h2><p class="muted">仅当指定成员发送对应关键词时回复。</p></div></div><div class="form"><label>成员 OpenID<input id="user-reply-id"></label><label>关键词<input id="user-reply-trigger"></label><label>回复内容<input id="user-reply-response"></label></div><button id="add-user-reply" class="button primary" style="margin-top:12px">保存专属回复</button><div id="user-reply-result" class="result"></div></div><div class="panel"><h3>已配置专属回复</h3><div id="user-reply-list"></div></div></div></section>
<section class="view" id="schedules"><div class="split"><div class="panel"><div class="panel-head"><div><h2>定时消息</h2><p class="muted">机器人按固定间隔向当前群发送消息。请避免设置过短间隔。</p></div></div><div class="form two"><label>发送间隔（分钟）<input id="schedule-minutes" type="number" min="1" max="525600" value="60"></label><label class="full">消息内容<textarea id="schedule-content" maxlength="2000"></textarea></label></div><button id="add-schedule" class="button primary" style="margin-top:12px">添加定时消息</button><div id="schedule-result" class="result"></div></div><div class="panel"><h3>当前群定时消息</h3><div id="schedule-list"></div></div></div></section>
<section class="view" id="group-admins"><div class="split"><div class="panel"><div class="panel-head"><div><h2>分管管理员</h2><p class="muted">分管管理员仅用于机器人内部命令授权，不会改变 QQ 官方群权限。</p></div></div><div class="form two"><label>成员 OpenID<input id="group-admin-id"></label><label>显示名称（可选）<input id="group-admin-name"></label></div><button id="add-group-admin" class="button primary" style="margin-top:12px">添加分管管理员</button><div id="group-admin-result" class="result"></div></div><div class="panel"><h3>当前分管管理员</h3><div id="group-admin-list"></div></div></div></section>
<section class="view" id="approval"><div class="panel"><div class="panel-head"><div><h2>入群审核</h2><p class="muted">调用 QQ 官方入群审核接口。官方群未获官方权限时会返回官方错误，不会伪造审核结果。</p></div><button id="refresh-approval" class="button">刷新申请</button></div><div id="approval-list"></div><div id="approval-result" class="result"></div></div></section>
<section class="view" id="moderation"><div class="split"><div class="panel"><div class="panel-head"><div><h2>手动群管</h2><p class="muted">使用成员 OpenID 执行禁言、解除禁言、踢出或加入官方黑名单。</p></div></div><div class="form"><label>成员 OpenID<input id="moderation-user"></label><label>操作<select id="moderation-action"><option value="mute">禁言</option><option value="unmute">解除禁言</option><option value="kick">踢出群聊</option><option value="blacklist">踢出并加入黑名单</option></select></label><label>禁言时长（分钟）<input id="moderation-minutes" type="number" min="1" max="43200" value="10"></label></div><button id="run-moderation" class="button danger" style="margin-top:12px">执行群管操作</button><div id="moderation-result" class="result"></div></div><div class="panel"><h3>撤回消息</h3><p class="muted">请填写官方机器人可撤回的消息 ID。成员消息是否可撤回取决于 QQ 官方接口权限。</p><div class="form two"><label>消息 ID<input id="recall-message-id"></label><div><button id="recall-message" class="button danger">尝试撤回</button></div></div></div></div></section>
<section class="view" id="blacklist"><div class="split"><div class="panel"><div class="panel-head"><div><h2>黑名单</h2><p class="muted">加入黑名单会通过 QQ 官方接口移出成员并拉黑。</p></div></div><div class="form two"><label>成员 OpenID<input id="blacklist-user"></label><label>备注（可选）<input id="blacklist-reason"></label></div><button id="add-blacklist" class="button danger" style="margin-top:12px">踢出并加入黑名单</button><div id="blacklist-result" class="result"></div></div><div class="panel"><h3>官方黑名单</h3><div id="blacklist-list"></div></div></div></section>
<section class="view" id="keyword-mute"><div class="panel"><div class="panel-head"><div><h2>关键词禁言</h2><p class="muted">命中关键词后禁言发言成员。</p></div></div><div class="form two"><label>关键词<input id="keyword-mute-trigger" maxlength="128"></label><label>禁言时长（分钟）<input id="keyword-mute-minutes" type="number" min="1" max="43200" value="10"></label></div><button class="button primary" data-save-rule="mute" style="margin-top:12px">添加禁言关键词</button><div id="keyword-mute-result" class="result"></div><div id="keyword-mute-list" style="margin-top:14px"></div></div></section>
<section class="view" id="keyword-kick"><div class="panel"><div class="panel-head"><div><h2>关键词踢出</h2><p class="muted">命中关键词后移出发言成员。</p></div></div><div class="form"><label>关键词<input id="keyword-kick-trigger" maxlength="128"></label></div><button class="button danger" data-save-rule="kick" style="margin-top:12px">添加踢出关键词</button><div id="keyword-kick-result" class="result"></div><div id="keyword-kick-list" style="margin-top:14px"></div></div></section>
<section class="view" id="keyword-blacklist"><div class="panel"><div class="panel-head"><div><h2>关键词拉黑</h2><p class="muted">命中关键词后移出成员并加入 QQ 官方群黑名单。</p></div></div><div class="form"><label>关键词<input id="keyword-blacklist-trigger" maxlength="128"></label></div><button class="button danger" data-save-rule="blacklist" style="margin-top:12px">添加拉黑关键词</button><div id="keyword-blacklist-result" class="result"></div><div id="keyword-blacklist-list" style="margin-top:14px"></div></div></section>
<section class="view" id="messages"><div class="panel"><div class="panel-head"><div><h2>群消息记录</h2><p class="muted">仅显示机器人实际收到并保存的消息。</p></div><button id="refresh-messages" class="button">刷新记录</button></div><div id="message-list"></div></div></section>
<section class="view" id="profile"><div class="panel"><div class="panel-head"><div><h2>账号资料</h2><p class="muted">登录账号与邮箱信息。</p></div></div><div class="form two"><label>账号<input id="profile-username" disabled></label><label>显示名称<input id="profile-name"></label><label class="full">邮箱<input id="profile-email" type="email"></label></div><button id="save-profile" class="button primary" style="margin-top:12px">保存资料</button><div id="profile-result" class="result"></div></div></section>
</div></main></div><script>
const api=async(url,opt={})=>{const r=await fetch(url,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'操作失败');return d};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const detail={auto_reply:'自动回复',user_replies:'用户专属回复',scheduled_messages:'定时消息',group_admins:'分管管理员',moderation:'手动群管',blacklist:'黑名单',keyword_mute:'关键词禁言',keyword_kick:'关键词踢出',keyword_blacklist:'关键词拉黑',join_approval:'入群审核',message_records:'群消息记录',scum_query:'SCUM 服务器'};
const detailView={auto_reply:'replies',user_replies:'user-replies',scheduled_messages:'schedules',group_admins:'group-admins',moderation:'moderation',blacklist:'blacklist',keyword_mute:'keyword-mute',keyword_kick:'keyword-kick',keyword_blacklist:'keyword-blacklist',join_approval:'approval',message_records:'messages',scum_query:'server'};
const labels={groups:['我的群','使用机器人授权卡注册账号后，在这里绑定并配置官方群。'],bind:['绑定官方群','当前账号授权有效时可直接绑定官方群。'],switches:['功能设置','每项功能均可进入独立页面完成具体设置。'],server:['SCUM 服务器','当前群的服务器绑定。'],replies:['自动回复','添加当前群关键词和回复内容。'],'user-replies':['用户专属回复','为指定成员保存独立回复。'],schedules:['定时消息','按固定间隔向当前群主动发送消息。'],'group-admins':['分管管理员','维护机器人内部管理权限。'],approval:['入群审核','查看并处理官方群入群申请。'],moderation:['手动群管','用官方 OpenID 执行群管理。'],blacklist:['黑名单','管理 QQ 官方群黑名单。'],'keyword-mute':['关键词禁言','独立维护命中后禁言的关键词。'],'keyword-kick':['关键词踢出','独立维护命中后踢出的关键词。'],'keyword-blacklist':['关键词拉黑','独立维护命中后拉黑的关键词。'],messages:['群消息记录','查看机器人已收到的群消息。'],profile:['账号资料','修改当前账号的资料。']};
let groups=[],scope='',config={};
const out=(id,text,ok=true)=>{const el=document.getElementById(id);if(!el)return;el.textContent=text;el.classList.toggle('error',!ok)};
const need=()=>{if(scope)return true;alert('请先绑定并选择官方群。');return false};
const post=(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)});
const rowList=(items,render,empty='暂无数据')=>items?.length?`<table><tbody>${items.map(render).join('')}</tbody></table>`:`<div class="empty">${empty}</div>`;
function setView(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const [title,subtitle]=labels[view]||labels.groups;document.getElementById('title').textContent=title;document.getElementById('subtitle').textContent=subtitle;refreshView(view).catch(e=>alert(e.message));}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>setView(button.dataset.view));
async function loadGroups(){groups=await api('/api/groups');const select=document.getElementById('scope-switch');if(!scope||!groups.some(x=>x.scope_id===scope))scope=groups[0]?.scope_id||'';select.innerHTML='<option value="">暂未选择群</option>'+groups.map(g=>`<option value="${esc(g.scope_id)}">${esc(g.numeric_group_id||g.scope_id)}${g.group_name?` · ${esc(g.group_name)}`:''}</option>`).join('');select.value=scope;document.getElementById('groups-list').innerHTML=groups.length?groups.map(g=>`<article class="card group-card" data-select-group="${esc(g.scope_id)}"><span class="tag">已授权</span><h3>${esc(g.group_name||'官方群')}</h3><div class="group-id">${esc(g.numeric_group_id||g.scope_id)}</div><p class="muted">点击进入该群设置</p></article>`).join(''):'<div class="empty">还没有已绑定的官方群。请先使用群授权卡绑定。</div>';document.querySelectorAll('[data-select-group]').forEach(x=>x.onclick=()=>{scope=x.dataset.selectGroup;select.value=scope;setView('switches')});}
async function loadConfig(){if(!need())return;config=await api('/api/group-config?scope_id='+encodeURIComponent(scope));document.getElementById('switch-list').innerHTML=(config.features||[]).map(f=>{const target=detailView[f.key]||'';const state=f.enabled?'已开启':'已关闭';return `<article class="card"><div class="feature-meta"><b>${esc(f.label)}</b><span class="${f.enabled?'tag':'tag off'}">${state}</span></div><p class="muted">${target?`可在“${esc(detail[f.key])}”单独设置内容、规则或对象。`:'该功能不需要额外参数，可直接启停。'}</p><div class="row-actions" style="margin-top:13px"><button class="button ${f.enabled?'subtle':'primary'}" data-feature-toggle="${esc(f.key)}" data-enabled="${f.enabled?'1':'0'}">${f.enabled?'停用':'启用'}</button>${target?`<button class="button" data-open-settings="${target}">设置内容</button>`:''}</div></article>`}).join('')||'<div class="empty">暂无可配置功能</div>';document.querySelectorAll('[data-feature-toggle]').forEach(b=>b.onclick=async()=>{try{await post('/api/group-config',{scope_id:scope,features:{[b.dataset.featureToggle]:b.dataset.enabled!=='1'}});out('switch-result','功能状态已保存');await loadConfig()}catch(e){out('switch-result',e.message,false)}});document.querySelectorAll('[data-open-settings]').forEach(b=>b.onclick=()=>setView(b.dataset.openSettings));document.getElementById('server-id').value=config.server_id||'';}
async function loadReplies(){if(!need())return;const items=await api('/api/replies?scope_id='+encodeURIComponent(scope));document.getElementById('reply-list').innerHTML=rowList(items,x=>`<tr><td>${esc(x.trigger)}</td><td>${esc(x.response)}</td><td><button class="button danger" data-delete-reply="${esc(x.trigger)}">删除</button></td></tr>`,'暂无自动回复');document.querySelectorAll('[data-delete-reply]').forEach(b=>b.onclick=async()=>{await post('/api/replies/delete',{scope_id:scope,trigger:b.dataset.deleteReply});await loadReplies()});}
async function loadUserReplies(){if(!need())return;const items=await api('/api/user-replies?scope_id='+encodeURIComponent(scope));document.getElementById('user-reply-list').innerHTML=rowList(items,x=>`<tr><td>${esc(x.user_id)}</td><td>${esc(x.trigger)}</td><td>${esc(x.response)}</td><td><button class="button danger" data-delete-user-reply="${esc(x.user_id)}" data-trigger="${esc(x.trigger)}">删除</button></td></tr>`,'暂无用户专属回复');document.querySelectorAll('[data-delete-user-reply]').forEach(b=>b.onclick=async()=>{await post('/api/user-replies/delete',{scope_id:scope,user_id:b.dataset.deleteUserReply,trigger:b.dataset.trigger});await loadUserReplies()});}
async function loadSchedules(){if(!need())return;const items=await api('/api/schedules?scope_id='+encodeURIComponent(scope));const target=document.getElementById('schedule-list');if(!target)return;target.innerHTML=rowList(items,x=>`<tr><td>#${x.schedule_id}</td><td>${Math.max(1,Math.floor((x.interval_seconds||0)/60))} 分钟</td><td>${esc(x.content)}</td><td><button class="button danger" data-delete-schedule="${x.schedule_id}">删除</button></td></tr>`,'暂无定时消息');document.querySelectorAll('[data-delete-schedule]').forEach(b=>b.onclick=async()=>{await post('/api/schedules/delete',{scope_id:scope,schedule_id:+b.dataset.deleteSchedule});await loadSchedules()});}
async function loadAdmins(){if(!need())return;const items=await api('/api/group-admins?scope_id='+encodeURIComponent(scope));document.getElementById('group-admin-list').innerHTML=rowList(items,x=>`<tr><td>${esc(x.display_name||'未命名')}</td><td>${esc(x.user_id)}</td><td><button class="button danger" data-delete-admin="${esc(x.user_id)}">删除</button></td></tr>`,'暂无分管管理员');document.querySelectorAll('[data-delete-admin]').forEach(b=>b.onclick=async()=>{await post('/api/group-admins',{scope_id:scope,user_id:b.dataset.deleteAdmin,action:'remove'});await loadAdmins()});}
async function loadBlacklist(){if(!need())return;const items=await api('/api/blacklist?scope_id='+encodeURIComponent(scope));document.getElementById('blacklist-list').innerHTML=rowList(items,x=>`<tr><td>${esc(x.user_id)}</td><td>${esc(x.reason||'')}</td><td><button class="button" data-delete-blacklist="${esc(x.user_id)}">移出黑名单</button></td></tr>`,'暂无黑名单成员');document.querySelectorAll('[data-delete-blacklist]').forEach(b=>b.onclick=async()=>{await post('/api/blacklist',{scope_id:scope,user_id:b.dataset.deleteBlacklist,action:'remove'});await loadBlacklist()});}
async function loadRules(action){if(!need())return;const items=await api('/api/keyword-rules?scope_id='+encodeURIComponent(scope)+'&action='+action);const id='keyword-'+action+'-list';document.getElementById(id).innerHTML=rowList(items,x=>`<tr><td>${esc(x.trigger)}</td><td>${action==='mute'?`${x.duration_minutes||10} 分钟`:'-'}</td><td><button class="button danger" data-delete-rule="${x.rule_id}">删除</button></td></tr>`,'暂无关键词规则');document.querySelectorAll('#'+id+' [data-delete-rule]').forEach(b=>b.onclick=async()=>{await post('/api/keyword-rules/delete',{scope_id:scope,rule_id:+b.dataset.deleteRule});await loadRules(action)});}
async function loadApproval(){if(!need())return;const data=await api('/api/join-requests?scope_id='+encodeURIComponent(scope));const items=Array.isArray(data)?data:(data.join_requests||data.items||data.list||data.data||[]);document.getElementById('approval-list').innerHTML=rowList(items,x=>{const member=x.member_openid||x.user_openid||x.openid||'';const request=x.join_request_id||x.request_id||x.id||'';return `<tr><td>${esc(member)}</td><td>${esc(request||'-')}</td><td>${esc(x.message||x.apply_reason||'')}</td><td><button class="button primary" data-approval="approve" data-member="${esc(member)}" data-request="${esc(request)}">通过</button><button class="button danger" data-approval="decline" data-member="${esc(member)}" data-request="${esc(request)}">拒绝</button></td></tr>`},'暂无待审核申请');document.querySelectorAll('[data-approval]').forEach(b=>b.onclick=async()=>{const payload={scope_id:scope,member_openid:b.dataset.member,join_request_id:b.dataset.request,operation:b.dataset.approval};if(b.dataset.approval==='decline')payload.reject_reason=prompt('拒绝原因（可留空）')||'';await post('/api/join-requests/approve',payload);out('approval-result','已提交审核操作');await loadApproval()});}
async function loadMessages(){if(!need())return;const items=await api('/api/messages?scope_id='+encodeURIComponent(scope)+'&limit=100');document.getElementById('message-list').innerHTML=rowList(items,x=>`<tr><td>${esc(x.created_at||x.time||'')}</td><td>${esc(x.user_id||x.author_id||'')}</td><td>${esc(x.content||x.message||'')}</td><td>${esc(x.message_id||'')}</td></tr>`,'暂无已保存消息');}
async function refreshView(view){if(view==='groups')return loadGroups();if(view==='bind'||view==='profile')return;if(!need())return;if(view==='switches'||view==='server')return loadConfig();if(view==='replies')return loadReplies();if(view==='user-replies')return loadUserReplies();if(view==='schedules')return loadSchedules();if(view==='group-admins')return loadAdmins();if(view==='approval')return loadApproval();if(view==='blacklist')return loadBlacklist();if(view.startsWith('keyword-'))return loadRules(view.replace('keyword-',''));if(view==='messages')return loadMessages();}
document.getElementById('scope-switch').onchange=async e=>{scope=e.target.value;await refreshView(document.querySelector('.view.active')?.id||'groups')};
document.getElementById('bind-group').onclick=async()=>{try{const r=await post('/api/user/groups/bind',{scope_id:document.getElementById('bind-scope').value.trim()});out('bind-result',r.message||'官方群已绑定');await loadGroups()}catch(e){out('bind-result',e.message,false)}};
document.getElementById('save-server').onclick=async()=>{try{await post('/api/group-config',{scope_id:scope,server_id:document.getElementById('server-id').value.trim()});out('server-result','服务器设置已保存')}catch(e){out('server-result',e.message,false)}};
document.getElementById('add-reply').onclick=async()=>{try{await post('/api/replies',{scope_id:scope,trigger:document.getElementById('reply-trigger').value.trim(),response:document.getElementById('reply-response').value.trim()});out('reply-result','自动回复已保存');document.getElementById('reply-trigger').value='';document.getElementById('reply-response').value='';await loadReplies()}catch(e){out('reply-result',e.message,false)}};
document.getElementById('add-user-reply').onclick=async()=>{try{await post('/api/user-replies',{scope_id:scope,user_id:document.getElementById('user-reply-id').value.trim(),trigger:document.getElementById('user-reply-trigger').value.trim(),response:document.getElementById('user-reply-response').value.trim()});out('user-reply-result','专属回复已保存');['user-reply-id','user-reply-trigger','user-reply-response'].forEach(id=>document.getElementById(id).value='');await loadUserReplies()}catch(e){out('user-reply-result',e.message,false)}};
document.getElementById('add-schedule').onclick=async()=>{try{await post('/api/schedules',{scope_id:scope,content:document.getElementById('schedule-content').value.trim(),interval_minutes:+document.getElementById('schedule-minutes').value});out('schedule-result','定时消息已添加');document.getElementById('schedule-content').value='';await loadSchedules()}catch(e){out('schedule-result',e.message,false)}};
document.getElementById('add-group-admin').onclick=async()=>{try{await post('/api/group-admins',{scope_id:scope,user_id:document.getElementById('group-admin-id').value.trim(),display_name:document.getElementById('group-admin-name').value.trim()});out('group-admin-result','分管管理员已保存');document.getElementById('group-admin-id').value='';document.getElementById('group-admin-name').value='';await loadAdmins()}catch(e){out('group-admin-result',e.message,false)}};
document.getElementById('refresh-approval').onclick=()=>loadApproval().catch(e=>out('approval-result',e.message,false));
document.getElementById('run-moderation').onclick=async()=>{try{await post('/api/moderation',{scope_id:scope,user_id:document.getElementById('moderation-user').value.trim(),action:document.getElementById('moderation-action').value,duration_minutes:+document.getElementById('moderation-minutes').value});out('moderation-result','群管操作已提交')}catch(e){out('moderation-result',e.message,false)}};
document.getElementById('recall-message').onclick=async()=>{try{await post('/api/moderation',{scope_id:scope,action:'recall',message_id:document.getElementById('recall-message-id').value.trim()});out('moderation-result','撤回操作已提交')}catch(e){out('moderation-result',e.message,false)}};
document.getElementById('add-blacklist').onclick=async()=>{try{await post('/api/blacklist',{scope_id:scope,user_id:document.getElementById('blacklist-user').value.trim(),reason:document.getElementById('blacklist-reason').value.trim()});out('blacklist-result','已加入官方黑名单');document.getElementById('blacklist-user').value='';document.getElementById('blacklist-reason').value='';await loadBlacklist()}catch(e){out('blacklist-result',e.message,false)}};
document.querySelectorAll('[data-save-rule]').forEach(b=>b.onclick=async()=>{const action=b.dataset.saveRule,id='keyword-'+action;try{await post('/api/keyword-rules',{scope_id:scope,action,trigger:document.getElementById(id+'-trigger').value.trim(),duration_minutes:action==='mute'?+document.getElementById(id+'-minutes').value:10});out(id+'-result','关键词规则已保存');document.getElementById(id+'-trigger').value='';await loadRules(action)}catch(e){out(id+'-result',e.message,false)}});
document.getElementById('refresh-messages').onclick=()=>loadMessages().catch(e=>alert(e.message));
document.getElementById('save-profile').onclick=async()=>{try{await post('/api/profile',{email:document.getElementById('profile-email').value.trim(),display_name:document.getElementById('profile-name').value.trim()});out('profile-result','资料已保存')}catch(e){out('profile-result',e.message,false)}};
document.getElementById('logout').onclick=async()=>{await fetch('__LOGOUT_ENDPOINT__',{method:'POST'});location.href='/'};
(async()=>{try{const [profile]=await Promise.all([api('/api/profile'),loadGroups()]);document.getElementById('user-label').textContent=profile.display_name||profile.username||'分群用户';document.getElementById('profile-username').value=profile.username||'';document.getElementById('profile-name').value=profile.display_name||'';document.getElementById('profile-email').value=profile.email||''}catch(e){alert(e.message)}})();
</script></body></html>"""
